import sys
from bs4 import BeautifulSoup
for fn in sys.argv[1:]:
 print('===',fn)
 soup=BeautifulSoup(open(fn,encoding='utf-8',errors='replace'),'html.parser')
 body=soup.select_one('[itemprop=\"articleBody\"]')
 for tag in body.find_all(['h1','h2','h3','h4','p','ol','ul','li','a']):
  if tag.name=='a':
   txt=' '.join(tag.get_text(' ',strip=True).split())
   if txt: print('A',txt,'HREF',tag.get('href'))
  elif tag.name in ['h1','h2','h3','h4','p','li']:
   txt=' '.join(tag.get_text(' ',strip=True).split())
   if txt: print(tag.name.upper(),txt)
PY"

